#include <iostream>

template <typename NODETYPE> class Tree;

template <typename NODETYPE>
class TreeNode {
    friend class Tree<NODETYPE>;
public:
    explicit TreeNode(const NODETYPE& val)
        : leftPtr{nullptr}, data{val}, rightPtr{nullptr} {}
    NODETYPE getData() const { return data; }
private:
    TreeNode<NODETYPE>* leftPtr;
    NODETYPE data;
    TreeNode<NODETYPE>* rightPtr;
};

template <typename NODETYPE>
class Tree {
public:
    Tree() : rootPtr{nullptr} {}
    ~Tree() { destroyTree(rootPtr); }

    void insertNode(const NODETYPE& value) {
        insertNodeHelper(&rootPtr, value);
    }

    void preOrderTraversal() const {
        preOrderHelper(rootPtr);
        std::cout << '\n';
    }

    void inOrderTraversal() const {
        inOrderHelper(rootPtr);
        std::cout << '\n';
    }

    void postOrderTraversal() const {
        postOrderHelper(rootPtr);
        std::cout << '\n';
    }

private:
    TreeNode<NODETYPE>* rootPtr;

    void insertNodeHelper(TreeNode<NODETYPE>** ptr, const NODETYPE& value) {
        if (*ptr == nullptr) {
            *ptr = new TreeNode<NODETYPE>(value);
        } else if (value < (*ptr)->data) {
            insertNodeHelper(&((*ptr)->leftPtr), value);
        } else if (value > (*ptr)->data) {
            insertNodeHelper(&((*ptr)->rightPtr), value);
        } else {
            std::cout << value << " dup\n";
        }
    }

    void preOrderHelper(TreeNode<NODETYPE>* ptr) const {
        if (ptr != nullptr) {
            std::cout << ptr->data << ' ';
            preOrderHelper(ptr->leftPtr);
            preOrderHelper(ptr->rightPtr);
        }
    }

    void inOrderHelper(TreeNode<NODETYPE>* ptr) const {
        if (ptr != nullptr) {
            inOrderHelper(ptr->leftPtr);
            std::cout << ptr->data << ' ';
            inOrderHelper(ptr->rightPtr);
        }
    }

    void postOrderHelper(TreeNode<NODETYPE>* ptr) const {
        if (ptr != nullptr) {
            postOrderHelper(ptr->leftPtr);
            postOrderHelper(ptr->rightPtr);
            std::cout << ptr->data << ' ';
        }
    }

    void destroyTree(TreeNode<NODETYPE>* ptr) {
        if (ptr != nullptr) {
            destroyTree(ptr->leftPtr);
            destroyTree(ptr->rightPtr);
            delete ptr;
        }
    }
};

int main() {
    Tree<int> intTree;
    int values[] = {50, 25, 75, 12, 33, 67, 88, 6, 13, 68};
    for (int val : values) {
        intTree.insertNode(val);
    }

    std::cout << "Preorder traversal:\n";
    intTree.preOrderTraversal();

    std::cout << "Inorder traversal:\n";
    intTree.inOrderTraversal();

    std::cout << "Postorder traversal:\n";
    intTree.postOrderTraversal();

    return 0;
}
